import React, { useEffect, useState } from 'react';
import { View, Text, Switch, TouchableOpacity, StyleSheet, ScrollView, Alert, Share } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { useRouter } from 'expo-router';
import { signOut, sendPasswordResetEmail, deleteUser } from 'firebase/auth';
import { doc, getDoc, updateDoc, deleteDoc, arrayRemove, collection, query, where, getDocs } from 'firebase/firestore';
import { auth, db } from '../config';
import { useTheme, BRAND } from '../constants/theme';
import { useLang, Lang } from '../constants/i18n';

export default function SettingsScreen() {
  const router = useRouter();
    const { isDark, toggleTheme, c } = useTheme();
      const { lang, setLang, t } = useLang();
        const [isPrivate, setIsPrivate] = useState(false);
          const [showOnline, setShowOnline] = useState(true);
            const [notifLikes, setNotifLikes] = useState(true);
              const [notifComments, setNotifComments] = useState(true);
                const [blocked, setBlocked] = useState<string[]>([]);
                  const uid = auth.currentUser?.uid;

                    useEffect(() => {
                        if (!uid) return;
                            getDoc(doc(db, 'users', uid)).then((snap) => {
                                  if (snap.exists()) {
                                          const d = snap.data();
                                                  setIsPrivate(!!d.isPrivate);
                                                          setShowOnline(d.showOnline !== false);
                                                                  setNotifLikes(d.notifLikes !== false);
                                                                          setNotifComments(d.notifComments !== false);
                                                                                  if (d.language === 'English' || d.language === 'Hindi' || d.language === 'Hinglish') setLang(d.language);
                                                                                          setBlocked(d.blockedUsers || []);
                                                                                                }
                                                                                                    });
                                                                                                      }, [uid]);

                                                                                                        const updatePref = async (patch: Record<string, any>) => {
                                                                                                            if (uid) await updateDoc(doc(db, 'users', uid), patch);
                                                                                                              };

                                                                                                                const handlePasswordReset = async () => {
                                                                                                                    const email = auth.currentUser?.email;
                                                                                                                        if (!email) return;
                                                                                                                            await sendPasswordResetEmail(auth, email);
                                                                                                                                Alert.alert('Email Sent', 'Password reset link sent to your email.');
                                                                                                                                  };

                                                                                                                                    const cycleLanguage = () => {
                                                                                                                                        const list: Lang[] = ['English', 'Hindi', 'Hinglish'];
                                                                                                                                            const next = list[(list.indexOf(lang) + 1) % list.length];
                                                                                                                                                setLang(next);
                                                                                                                                                    updatePref({ language: next });
                                                                                                                                                      };

                                                                                                                                                        const downloadMyData = async () => {
                                                                                                                                                            if (!uid) return;
                                                                                                                                                                const uSnap = await getDoc(doc(db, 'users', uid));
                                                                                                                                                                    const pSnap = await getDocs(query(collection(db, 'posts'), where('uid', '==', uid)));
                                                                                                                                                                        const payload = {
                                                                                                                                                                              profile: uSnap.data() || {},
                                                                                                                                                                                    posts: pSnap.docs.map((d) => ({ id: d.id, ...d.data() })),
                                                                                                                                                                                          exportedAt: new Date().toISOString(),
                                                                                                                                                                                              };
                                                                                                                                                                                                  await Share.share({ message: JSON.stringify(payload, null, 2), title: 'Flevora Personal Data' });
                                                                                                                                                                                                    };

                                                                                                                                                                                                      const showPolicy = (title: string, msg: string) => Alert.alert(title, msg);

                                                                                                                                                                                                        const deactivateAccount = () => {
                                                                                                                                                                                                            Alert.alert('Deactivate Account', 'Hide your account until you log back in?', [
                                                                                                                                                                                                                  { text: 'Cancel', style: 'cancel' },
                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                text: 'Deactivate',
                                                                                                                                                                                                                                        style: 'destructive',
                                                                                                                                                                                                                                                onPress: async () => {
                                                                                                                                                                                                                                                          if (uid) await updateDoc(doc(db, 'users', uid), { status: 'deactivated', isOnline: false });
                                                                                                                                                                                                                                                                    await signOut(auth);
                                                                                                                                                                                                                                                                            },
                                                                                                                                                                                                                                                                                  },
                                                                                                                                                                                                                                                                                      ]);
                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                          const unblockUser = async (targetId: string) => {
                                                                                                                                                                                                                                                                                              if (!uid) return;
                                                                                                                                                                                                                                                                                                  await updateDoc(doc(db, 'users', uid), { blockedUsers: arrayRemove(targetId) });
                                                                                                                                                                                                                                                                                                      setBlocked((prev) => prev.filter((id) => id !== targetId));
                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                          const handleDeleteAccount = () => {
                                                                                                                                                                                                                                                                                                              Alert.alert('Delete Account', 'All your posts, stories, notifications, and profile will be permanently deleted. Continue?', [
                                                                                                                                                                                                                                                                                                                    { text: 'Cancel', style: 'cancel' },
                                                                                                                                                                                                                                                                                                                          {
                                                                                                                                                                                                                                                                                                                                  text: 'Delete',
                                                                                                                                                                                                                                                                                                                                          style: 'destructive',
                                                                                                                                                                                                                                                                                                                                                  onPress: async () => {
                                                                                                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                                                                                                                        if (uid && auth.currentUser) {
                                                                                                                                                                                                                                                                                                                                                                                      const [pSnap, sSnap, nToSnap, nFromSnap] = await Promise.all([
                                                                                                                                                                                                                                                                                                                                                                                                      getDocs(query(collection(db, 'posts'), where('uid', '==', uid))),
                                                                                                                                                                                                                                                                                                                                                                                                                      getDocs(query(collection(db, 'stories'), where('uid', '==', uid))),
                                                                                                                                                                                                                                                                                                                                                                                                                                      getDocs(query(collection(db, 'notifications'), where('toUid', '==', uid))),
                                                                                                                                                                                                                                                                                                                                                                                                                                                      getDocs(query(collection(db, 'notifications'), where('fromUid', '==', uid))),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  await Promise.all([
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ...pSnap.docs.map((d) => deleteDoc(d.ref)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ...sSnap.docs.map((d) => deleteDoc(d.ref)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ...nToSnap.docs.map((d) => deleteDoc(d.ref)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ...nFromSnap.docs.map((d) => deleteDoc(d.ref)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              await deleteDoc(doc(db, 'users', uid));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            await deleteUser(auth.currentUser);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } catch {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Alert.alert('Re-login Required', 'Please log out and log back in before deleting your account.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <ScrollView style={[styles.container, { backgroundColor: c.background }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <View style={[styles.header, { borderBottomColor: c.border }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <TouchableOpacity onPress={() => router.back()}><Ionicons name="arrow-back" size={24} color={c.text} /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Text style={[styles.title, { color: c.text }]}>{t.settings}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </View>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity style={[styles.row, { borderBottomColor: c.border }]} onPress={() => router.navigate('/profile' as any)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Text style={[styles.label, { color: c.text }]}>{t.editProfile}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Ionicons name="chevron-forward" size={20} color={c.muted} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <View style={[styles.row, { borderBottomColor: c.border }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Text style={[styles.label, { color: c.text }]}>{t.privateAcc}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Switch value={isPrivate} onValueChange={(v) => { setIsPrivate(v); updatePref({ isPrivate: v }); }} trackColor={{ true: BRAND }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <View style={[styles.row, { borderBottomColor: c.border }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Text style={[styles.label, { color: c.text }]}>{t.activity}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Switch value={showOnline} onValueChange={(v) => { setShowOnline(v); updatePref({ showOnline: v, isOnline: v }); }} trackColor={{ true: BRAND }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <View style={[styles.row, { borderBottomColor: c.border }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Text style={[styles.label, { color: c.text }]}>{t.darkMode}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Switch value={isDark} onValueChange={() => { toggleTheme(); updatePref({ darkMode: !isDark }); }} trackColor={{ true: BRAND }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <View style={[styles.row, { borderBottomColor: c.border }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Text style={[styles.label, { color: c.text }]}>{t.likeNotif}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Switch value={notifLikes} onValueChange={(v) => { setNotifLikes(v); updatePref({ notifLikes: v }); }} trackColor={{ true: BRAND }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <View style={[styles.row, { borderBottomColor: c.border }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Text style={[styles.label, { color: c.text }]}>{t.commentNotif}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Switch value={notifComments} onValueChange={(v) => { setNotifComments(v); updatePref({ notifComments: v }); }} trackColor={{ true: BRAND }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <TouchableOpacity style={[styles.row, { borderBottomColor: c.border }]} onPress={cycleLanguage}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Text style={[styles.label, { color: c.text }]}>{t.language}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Text style={{ color: BRAND, fontWeight: '700' }}>{lang}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <TouchableOpacity style={[styles.row, { borderBottomColor: c.border }]} onPress={handlePasswordReset}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Text style={[styles.label, { color: c.text }]}>{t.changePass}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Ionicons name="chevron-forward" size={20} color={c.muted} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity style={[styles.row, { borderBottomColor: c.border }]} onPress={downloadMyData}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Text style={[styles.label, { color: c.text }]}>{t.downloadData}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Ionicons name="download-outline" size={20} color={BRAND} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <TouchableOpacity style={[styles.row, { borderBottomColor: c.border }]} onPress={() => showPolicy('Privacy Policy', 'Flevora stores only your profile, posts, and messages securely in Firebase & Cloudinary. You can export or delete your data anytime.')}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Text style={[styles.label, { color: c.text }]}>{t.privacy}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Ionicons name="document-text-outline" size={20} color={c.muted} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <TouchableOpacity style={[styles.row, { borderBottomColor: c.border }]} onPress={() => showPolicy('Community Guidelines', 'Respect all users. No spam, harassment, hate speech, or illegal content. Violations may lead to content removal or account suspension.')}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Text style={[styles.label, { color: c.text }]}>{t.guidelines}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Ionicons name="shield-checkmark-outline" size={20} color={c.muted} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </TouchableOpacity>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Text style={[styles.section, { color: c.muted }]}>Blocked Users ({blocked.length})</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {blocked.map((id) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <View key={id} style={[styles.row, { borderBottomColor: c.border }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Text style={{ color: c.text }}>{id.slice(0, 12)}...</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <TouchableOpacity onPress={() => unblockUser(id)}><Text style={{ color: BRAND, fontWeight: '600' }}>Unblock</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ))}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity style={styles.logoutBtn} onPress={() => signOut(auth)}><Text style={styles.logoutText}>{t.logout}</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity style={styles.deactBtn} onPress={deactivateAccount}><Text style={styles.deactText}>{t.deactivate}</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <TouchableOpacity style={styles.deleteBtn} onPress={handleDeleteAccount}><Text style={styles.deleteText}>{t.deleteAcc}</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </ScrollView>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const styles = StyleSheet.create({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  container: { flex: 1, paddingTop: 48 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    header: { flexDirection: 'row', alignItems: 'center', padding: 16, borderBottomWidth: 1, gap: 14 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      title: { fontSize: 18, fontWeight: '700' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        row: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', padding: 16, borderBottomWidth: 1 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          label: { fontSize: 15, fontWeight: '500' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            section: { fontSize: 13, fontWeight: '600', paddingHorizontal: 16, paddingTop: 20, paddingBottom: 8 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              logoutBtn: { margin: 16, marginTop: 24, padding: 14, borderRadius: 12, backgroundColor: '#F3F4F6', alignItems: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                logoutText: { color: '#111827', fontWeight: '700' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  deactBtn: { marginHorizontal: 16, marginBottom: 10, padding: 14, borderRadius: 12, backgroundColor: '#FEF3C7', alignItems: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    deactText: { color: '#B45309', fontWeight: '700' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      deleteBtn: { marginHorizontal: 16, marginBottom: 40, padding: 14, borderRadius: 12, backgroundColor: '#FEE2E2', alignItems: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        deleteText: { color: '#DC2626', fontWeight: '700' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        